:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --primary: #6c5ce7;
  --accent: #00cec9;
  --text: #f0f0f5;
  --text-muted: #a0a0b8;
  --card-back: #3a3a5a;
  --card-border: #4a4a6a;
  --radius: 12px;
  --transition: 0.3s ease;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

.game-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.stats {
  display: flex;
  align-items: center;
  gap: 16px;
  font-size: 1rem;
  color: var(--text-muted);
}

#move-count {
  color: var(--accent);
  font-weight: 700;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  background: var(--primary);
  color: var(--text);
  border: none;
  border-radius: 8px;
  padding: 10px 20px;
  cursor: pointer;
  transition: background var(--transition), transform 0.1s ease;
  min-height: 44px;
}

.btn:hover {
  background: #7d6ff0;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
  background: #5a4bd1;
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.card {
  aspect-ratio: 1;
  border-radius: 8px;
  background: var(--card-back);
  border: 2px solid var(--card-border);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition), background var(--transition), border-color var(--transition);
  position: relative;
  transform-style: preserve-3d;
  user-select: none;
  min-width: 0;
}

.card:hover:not(.matched):not(.flipped) {
  border-color: var(--accent);
  transform: scale(1.04);
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card.flipped {
  background: var(--card-color, #fff);
  border-color: var(--card-color, #fff);
}

.card.matched {
  background: var(--card-color, #fff);
  border-color: var(--accent);
  cursor: default;
  opacity: 0.85;
}

.card.matched::after {
  content: '✓';
  position: absolute;
  font-size: 1.8rem;
  color: rgba(0, 0, 0, 0.5);
  font-weight: 700;
}

.card .card-label {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.win-message {
  margin-top: 20px;
  padding: 16px;
  background: var(--primary);
  border-radius: var(--radius);
  text-align: center;
  font-size: 1.25rem;
  font-weight: 700;
  animation: pop 0.4s ease;
}

@keyframes pop {
  0% { transform: scale(0.8); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

@media (max-width: 420px) {
  .game-container {
    padding: 16px;
  }
  .game-board {
    gap: 8px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .stats {
    font-size: 0.9rem;
  }
  .btn {
    padding: 8px 16px;
    font-size: 0.9rem;
  }
}

@media (max-width: 360px) {
  .game-board {
    gap: 6px;
  }
  .game-container {
    padding: 12px;
  }
}

(function () {
  'use strict';

  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const board = document.getElementById('game-board');
  const moveCountEl = document.getElementById('move-count');
  const winMessage = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game');

  let cards = [];
  let flipped = [];
  let matchedPairs = 0;
  let moves = 0;
  let lockBoard = false;

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
  }

  function createCard(color, index) {
    const card = document.createElement('div');
    card.className = 'card';
    card.setAttribute('role', 'button');
    card.setAttribute('tabindex', '0');
    card.setAttribute('aria-label', 'Hidden card ' + (index + 1));
    card.dataset.color = color;
    card.dataset.index = index;
    card.style.setProperty('--card-color', color);

    card.addEventListener('click', onCardClick);
    card.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        onCardClick.call(card);
      }
    });

    return card;
  }

  function onCardClick() {
    if (lockBoard) return;
    if (this.classList.contains('flipped') || this.classList.contains('matched')) return;

    this.classList.add('flipped');
    this.setAttribute('aria-label', 'Card ' + (parseInt(this.dataset.index, 10) + 1) + ', color revealed');
    flipped.push(this);

    if (flipped.length === 2) {
      moves++;
      moveCountEl.textContent = moves;
      checkMatch();
    }
  }

  function checkMatch() {
    const [a, b] = flipped;
    if (a.dataset.color === b.dataset.color) {
      a.classList.add('matched');
      b.classList.add('matched');
      a.setAttribute('aria-label', 'Matched card');
      b.setAttribute('aria-label', 'Matched card');
      a.removeAttribute('tabindex');
      b.removeAttribute('tabindex');
      matchedPairs++;
      flipped = [];
      if (matchedPairs === COLORS.length) {
        winMessage.hidden = false;
      }
    } else {
      lockBoard = true;
      setTimeout(function () {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.setAttribute('aria-label', 'Hidden card ' + (parseInt(a.dataset.index, 10) + 1));
        b.setAttribute('aria-label', 'Hidden card ' + (parseInt(b.dataset.index, 10) + 1));
        flipped = [];
        lockBoard = false;
      }, 800);
    }
  }

  function initGame() {
    board.innerHTML = '';
    flipped = [];
    matchedPairs = 0;
    moves = 0;
    lockBoard = false;
    moveCountEl.textContent = '0';
    winMessage.hidden = true;

    const deck = [];
    COLORS.forEach(function (color) {
      deck.push(color, color);
    });
    shuffle(deck);

    deck.forEach(function (color, i) {
      board.appendChild(createCard(color, i));
    });
  }

  newGameBtn.addEventListener('click', initGame);

  initGame();
})();
